import {Chess} from './chess.js';
import {mapMovement,pieceNames} from './movement.js';
const icons={p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚'},label={legal:'Can move',capture:'Can capture',blocked:'Blocked',attack:'Attacked square',unsafe:'King safety',pattern:'Outside its movement pattern',origin:'Selected piece'};
export function mountExplorer(document,getFen){
 const $=id=>document.getElementById(id);let branch=null,from='e2',view='position',type='n',color='w',origin='d4',map=null,target=null,paths=true;
 const squareOptions=()=>Array.from({length:64},(_,i)=>String.fromCharCode(97+i%8)+(8-Math.floor(i/8)));
 $('map-origin').innerHTML=squareOptions().map(s=>`<option value="${s}">${s}</option>`).join('');$('map-origin').value=origin;
 function choices(){let pieces=branch.board().flat().filter(Boolean);$('map-piece').innerHTML=pieces.map(p=>`<option value="${p.square}">${p.color==='w'?'White':'Black'} ${pieceNames[p.type]} · ${p.square}</option>`).join('');if(!branch.get(from))from=pieces.find(p=>p.color===branch.turn())?.square||pieces[0].square;$('map-piece').value=from;}
 function paint(){map=mapMovement({fen:branch.fen(),from:view==='open'?origin:from,type,color,open:view==='open'});let selected=map.piece;$('map-heading').textContent=`${pieceNames[selected.type][0].toUpperCase()+pieceNames[selected.type].slice(1)} on ${map.from}`;$('map-context').textContent=view==='open'?'Movement pattern only. No blockers or opposing attacks are present.':map.hypothetical?`Hypothetical view: as if ${selected.color==='w'?'White':'Black'} could move now. In the game it is ${map.actualTurn==='w'?'White':'Black'}’s turn.`:`All legal options for this piece. ${map.actualTurn==='w'?'White':'Black'} to move.`;
 $('map-piece-label').hidden=view==='open';$('map-open-controls').hidden=view!=='open';$('map-back').disabled=view==='open'||!branch.history().length;$('map-reset').disabled=view==='open';
 $('map-board').innerHTML='';let destinations=map.cells.filter(c=>['legal','capture'].includes(c.status)),lines=[];
 const center=s=>[s.charCodeAt(0)-97+.5,8-+s[1]+.5];let [sx,sy]=center(map.from);
 for(let cell of map.cells){let piece=view==='open'?(cell.to===origin?{type,color}:null):branch.get(cell.to);let b=document.createElement('button');b.className=`square ${(cell.to.charCodeAt(0)-97+ +cell.to[1])%2===0?'dark':''} map-${cell.status}${target===cell.to?' map-inspected':''}`;b.setAttribute('aria-label',`${cell.to}: ${label[cell.status]}${piece?', '+(piece.color==='w'?'white':'black')+' '+pieceNames[piece.type]:''}`);b.title=`${cell.to}: ${label[cell.status]}`;b.dataset.square=cell.to;b.innerHTML=(piece?`<span class="piece ${piece.color==='w'?'white':'black'}" aria-hidden="true">${icons[piece.type]}</span>`:'')+`<span class="map-coordinate">${cell.to}</span>`+(cell.status==='blocked'?'<span class="map-mark">×</span>':cell.status==='unsafe'?'<span class="map-mark">!</span>':cell.status==='attack'?'<span class="map-mark">◇</span>':'');b.onclick=()=>{target=cell.to;paint();};b.onkeydown=e=>{const offsets={ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8};if(e.key in offsets){e.preventDefault();let items=[...$('map-board').children],i=items.indexOf(b)+offsets[e.key];items[i]?.focus();}};$('map-board').append(b);}
 if(paths)for(let cell of destinations){let [tx,ty]=center(cell.to);let points=selected.type==='n'?`${sx},${sy} ${sx},${ty} ${tx},${ty}`:`${sx},${sy} ${tx},${ty}`;lines.push(`<polyline points="${points}" fill="none" stroke="${cell.status==='capture'?'#73311a':'#354d15'}" stroke-width=".035" opacity=".6"/><circle cx="${tx}" cy="${ty}" r=".085" fill="#354d15"/>`);}
 $('map-lines').innerHTML=lines.join('');$('map-count').textContent=`${destinations.length} destinations${view==='position'?' · '+map.legalMoves.length+' legal moves':''}`;
 $('map-destinations').innerHTML=destinations.map(c=>`<button data-destination="${c.to}" class="destination ${c.status}">${c.to}${c.status==='capture'?' ×':''}${c.moves.length>1?' · 4 promotions':''}</button>`).join('')||'<p>No legal destinations for this piece. Inspect the marked squares to learn why.</p>';
 $('map-destinations').querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{target=b.dataset.destination;paint();});
 let cell=map.cells.find(c=>c.to===target);$('map-square-title').textContent=cell?`${cell.to} · ${label[cell.status]}`:'Why can—or can’t—it go there?';$('map-reason').textContent=cell?cell.reason:'Select any of the 64 squares to inspect it. Green destinations are legal moves; orange destinations are captures. The list above includes every legal destination.';
 $('map-try').hidden=!cell?.moves.length||view==='open';$('map-promotion-label').hidden=!cell?.moves.some(m=>m.promotion);$('map-try').textContent=map.hypothetical?'Try in a hypothetical position →':'Try this move & map the reply →';
 $('map-trail').textContent=branch.history().length?'Your exploration: '+branch.history().join(' → '):'Your real game stays unchanged.';
 if(target)[...$('map-board').children].find(b=>b.dataset.square===target)?.focus({preventScroll:true});
 }
 $('open-map').onclick=()=>{branch=new Chess(getFen());from=branch.board().flat().find(p=>p?.color===branch.turn()&&p.type==='n')?.square||branch.board().flat().find(p=>p?.color===branch.turn()).square;target=null;choices();paint();$('movement-dialog').showModal();};
 $('map-close').onclick=()=>$('movement-dialog').close();$('map-view').onchange=e=>{view=e.target.value;target=null;paint();};$('map-piece').onchange=e=>{from=e.target.value;target=null;paint();};$('map-type').onchange=e=>{type=e.target.value;target=null;paint();};$('map-color').onchange=e=>{color=e.target.value;target=null;paint();};$('map-origin').onchange=e=>{origin=e.target.value;target=null;paint();};$('map-paths').onchange=e=>{paths=e.target.checked;paint();};
 $('map-try').onclick=()=>{const cell=map.cells.find(c=>c.to===target);if(!cell?.moves.length)return;if(map.hypothetical)branch=new Chess(map.fen);let move=cell.moves.find(m=>m.promotion===$('map-promotion').value)||cell.moves[0];branch.move(move);from=branch.board().flat().find(p=>p?.color===branch.turn()&&branch.moves({square:p.square}).length)?.square||branch.board().flat().find(p=>p?.color===branch.turn()).square;target=null;choices();paint();};
 $('map-back').onclick=()=>{branch.undo();target=null;from=branch.board().flat().find(p=>p?.color===branch.turn()).square;choices();paint();};$('map-reset').onclick=()=>{branch=new Chess(getFen());target=null;choices();paint();};
}
